[entities]
// The Glimmering Cave: the moon-crystal it is lit by, standing and hung from its roof; the Glassmites
// folded among the crystals; a coffer in the side grotto; the cave's mouth onto the overlook; and on
// the overlook, the shrine, the view and the grand stair down into the court.
Y = moon_crystal size=1.2
ŷ = moon_crystal size=0.7
H = hanging_crystal
T = glassmite
U = chest item=ember_draught count=2 gold=80 model=coffer
X = crystal_arch yaw=-90 height=8
P = hint text="Below lies Vesperholm, the Moonbound City.|The moon over it has not moved since the night the Duchess wed it."
Z = moon_stair run=12 rise=0.5 steps=5 width=3 yaw=-90 on=λ
// The lamps on the piers down the flight, burning warm as the city's.
Ł = light y=4.3 color=1.7,0.72,0.22 radius=8 on=η
ł = light y=4.3 color=1.7,0.72,0.22 radius=8 on=γ
// The Vesper Gate home to Harrowmere, at the cave's far end, and the shrine on the overlook.
A = exit map=harrowmere at=40,2,90 label=Return_to_Harrowmere model=vesper_gate yaw=-90
B = save_statue
Q = hint text="The moon here never sets, and it keeps all it shines on.|Nothing in this city has died. Nothing in it lives."
R = hint text="Far below, a bridge of stone lies sunk in the gorge.|Whatever raises it lies on the far side."
// Duchess Ilvane in the choir of her cathedral, behind its great door (on passage floor: its vault
// is low, so the wall stands solid from just over the door's lintel up to the nave's ceiling).
D = moon_duchess
E = door boss=duchess_dead on=p
// Her choir's second mouth, a back door in its east wall (`rear`: the compass never points at it, as
// it is no way in): it shuts with the great door and opens when she falls, onto the old stair's foot,
// level with the choir, and the stair north up through the wall and its tower, the flying stair west over the drop behind the cathedral, the
// Moon Terrace and the grand stair up to Lyra's Chapel on its crag, high over her choir.
Ê = door boss=duchess_dead rear on=p
ê = hint text="A stair older than the cathedral climbs into the wall.|Above, something silver answers the moon." on=τ
ë = light y=2.6 color=0.6,0.7,1.0 radius=6 on=π
Þ = stair_flight run=5 rise=0.6 steps=5 width=1 yaw=90 on=ρ
ӂ = stair_flight run=9 rise=0.5 steps=4 width=1 yaw=0 on=д
ё = moon_stair run=6 rise=0.5 steps=5 width=3 yaw=90 on=ч
// The chapel: its front on the forecourt, a lesser gate of the cathedral's kind, a spire either side;
// its grand roof, steeper and higher than the cathedral's; pillars, moon-glass and candles down its
// nave, the handmaids' statues between them, and cold lights.
ю = moon_portal yaw=90 height=14.5 rose=17 on=щ
э = moon_spire height=36 on=Щ
ь = moon_roof span=15,9 ridge=z top=26 pitch=10 eave=0.5 grand on=Щ
ы = pillar on=щ
ъ = moon_window rise=4 size=1.7 on=щ
х = candles on=щ
п = light y=3 color=0.6,0.7,1.0 radius=9 on=щ
// The altar of Lyra the Embracer in the middle of her nave, the Argent Sigil the Duchess wed the moon
// on in the old god's hands. In the apse behind her stands an arch of her pale moonstone, empty and
// dark; once the sigil is lifted, the moon's light pours into it and opens there into a portal to
// Herran's Castle on the Hollow Peak (`hidden`: it can't be taken before).
ÿ = exit map=herrans_castle at=19,81,-90 label=Step_through_the_portal model=argent_portal yaw=90 requires=argent_sigil_taken hidden on=щ
þ = altar item=argent_sigil model=lyra yaw=90 on=щ said="You lift the Argent Sigil out of Lyra's open hands. They stay open.|Behind her, the moonlight pours into the apse and does not stop."
// The great bridge over the gorge, three abreast and four long, sunk 18 m down on the gorge floor until
// the lever in the bailey raises it out of the deep: the short way back to the shrine.
F = bridge lever=vesper_bridge rise=18 deck=0 on=_
G = lever id=vesper_bridge
// A false wall behind the square's east houses, into a hidden court.
W = secret_wall on=,
// The moonlit dead: sentinels of silvered plate, lantern wraiths, moonhounds and veiled knights.
S = pale_sentinel
L = lantern_wraith
M = moonhound
V = veiled_knight
// Finds: remedies, and gold the dead no longer spend.
C = chest item=red_tonic count=2 gold=90
I = chest item=blue_moss count=2 gold=120
J = chest item=grave_lily gold=160 model=coffer
K = chest item=menders_kit gold=140 model=banded
N = chest item=clotting_salve count=2 gold=110
O = chest item=bitter_root count=2 gold=100 model=coffer
// Light: the city's lamps burning warm under the moon, windows of moon-glass, and cold lights in the
// cathedral.
Ä = moon_lamp
Ó = moon_lamp
Ô = moon_lamp
Ö = moon_window on=n
Ü = moon_window on=c
// The great windows of the choir's back wall, three tall lights of stained moon-glass under a rose,
// glowing through the wall both ways: inside over the Duchess's choir (`Ӂ`), and outside over the drop
// behind the cathedral (`Ѣ`, hung from the chasm's floor), seen from the climb, the Moon Terrace and
// the chapel's forecourt.
Ӂ = moon_great_window rise=0.6 size=2.1 on=c
Ѣ = moon_great_window rise=19.2 size=2.2 on=_
Ú = moon_window on=a
Ñ = light y=3 color=0.6,0.7,1.0 radius=9 on=c
Ò = light y=3 color=0.62,0.72,1.0 radius=7
Û = light y=2.5 color=0.6,0.7,1.0 radius=8
Ç = candles on=c
Ù = candles on=a
// Dressing.
Å = veiled_statue
Æ = silver_tree
È = pillar on=n
É = pew yaw=-90 on=n
// The skyline: slender spires on the castle's walls, and the cathedral's two great spires.
Õ = moon_spire height=16 on=#
Ø = moon_spire height=24 on=%
// Roofs of silvered slate in polychrome courses, crested in iron, with dormers and chimney stacks,
